```php
/**
 * 查找最长无重复子串
 * @param $s
 * @return int|mixed
 */
function lengthOfLongestSubstring($s) {
    $n = strlen($s);
    $ans = 0;
    // 左右指针: 用两个指针left和right来表示滑动窗口的左右边界。
    $left = 0;
    $right = 0;
    $set = [];      // 哈希表: 用一个哈希表来记录窗口中出现的字符。
    while ($right < $n) {
        $c = $s[$right];
        // 窗口滑动: 当遇到重复字符时，左指针向右移动，直到窗口中不再包含重复字符。
        while (isset($set[$c])) {
            unset($set[$s[$left]]);
            $left++;
        }
        $set[$c] = true;
        $ans = max($ans, $right - $left + 1);
        $right++;
    }
    return $ans;
}

