    private static function countNodes(Game $game, $depth, $maximizing = true) {
        if ($depth == 0 || $game->isGameOver()) {
            return 1;
        }

        $count = 0;
        foreach ($game->getLegalMoves() as $move) {
            $game->makeMove($move);
            $count += self::countNodes($game, $depth - 1, !$maximizing);
            $game->undoMove($move);
        }

        return $count;
    }
