     * 生成帧校验和
     */
    private function generateFrameChecksum($frame) {
        $checksum = md5(serialize($this->gameState));
        echo "帧 {$frame} 校验和: {$checksum}\n";
        return $checksum;
    }

    /**
     * 获取当前游戏状态
     */
    public function getCurrentState() {
        return $this->gameState;
    }
}

?>
```

