class DynamicWeightedRandom {
    private $baseWeights;
    private $dynamicFactors;

    public function __construct($baseWeights) {
        $this->baseWeights = $baseWeights;
        $this->dynamicFactors = array_fill_keys(array_keys($baseWeights), 1);
    }

    /**
     * 根据用户行为动态调整权重
