```php
function bubbleSort($arr){
    $n = count($arr);
    for ($i=0; $i<$n-1; $i++){
        for ($j=$i+1; $j<$n; $j++){
            if ($arr[$j] < $arr[$i]){
                [$arr[$i], $arr[$j]] = [$arr[$j], $arr[$i]];
            }
        }
    }

    return $arr;
}

$arr = [45,2,5,54,3,23];
