	$html .= '				<th>允许非空</th>'."\n";
	$html .= '				<th>自动递增</th>'."\n";
	$html .= '				<th>是否主键</th>'."\n";
	$html .= '				<th>备注</th>'."\n";
	$html .= '			</tr>'."\n";

    foreach ($v['COLUMN'] as $f) {
